namespace emon;


public static class Ocrtest {
    [Xunit.Fact]
    public static void TestAnAnswerWithNoExtensionHasNone() {
        emon.Port.Cells c = emon.Port.NewCells();
        int at = Plan.AnOcr(c, 3);
        int w = Plan.AnOcrWord(c, at, 10, 20, 30, 40, 900, 0, 0);
        Plan.AnOcrCp(c, w, 97);
        Plan.AnOcrEnd(c, at);
        emon.Testport.AssertEq(Ocr.OxFind(c, at), -1, "the words are all there is");
    }
    [Xunit.Fact]
    public static void TestTheExtensionFollowsTheWordsAndReadsBack() {
        emon.Port.Cells c = emon.Port.NewCells();
        int at = Plan.AnOcr(c, 3);
        int w0 = Plan.AnOcrWord(c, at, 10, 20, 30, 40, 900, 0, 0);
        Plan.AnOcrCp(c, w0, 72);
        Plan.AnOcrCp(c, w0, 105);
        int w1 = Plan.AnOcrWord(c, at, 50, 20, 30, 40, 800, 0, 0);
        Plan.AnOcrCp(c, w1, 33);
        Ocr.OxBegin(c, 1, 2, 3, -85, 90, 1281455214, 17, 187, 1);
        Ocr.OxLine(c, 10, 18, 70, 44, 10, 60, 80, 62, 0, 0, 1);
        int x0 = Ocr.OxWord(c, 65, 1701734144);
        int s0 = Ocr.OxSym(c, x0, 10, 20, 15, 40, 950);
        Ocr.OxSymCp(c, s0, 72);
        int a0 = Ocr.OxAlt(c, s0, 120);
        Ocr.OxAltCp(c, a0, 75);
        int a1 = Ocr.OxAlt(c, s0, 80);
        Ocr.OxAltCp(c, a1, 78);
        Ocr.OxAltCp(c, a1, 77);
        int s1 = Ocr.OxSym(c, x0, 25, 20, 15, 40, 900);
        Ocr.OxSymCp(c, s1, 105);
        int x1 = Ocr.OxWord(c, 0, 0);
        int s2 = Ocr.OxSym(c, x1, 50, 20, 30, 40, 800);
        Ocr.OxSymCp(c, s2, 33);
        Plan.AnOcrEnd(c, at);
        int ext = Ocr.OxFind(c, at);
        emon.Testport.AssertThat(ext >= 0, "the extension is found after the two words");
        int n1 = Plan.AwNext(c, w0);
        emon.Testport.AssertEq(ext, Plan.AwNext(c, n1), "right after the last word");
        emon.Testport.AssertEq(Ocr.OxGet(c, ext, 0), Ocr.OxVersion(), "version");
        emon.Testport.AssertEq(Ocr.OxOrient(c, ext), 1, "orient");
        emon.Testport.AssertEq(Ocr.OxWdir(c, ext), 2, "writing direction");
        emon.Testport.AssertEq(Ocr.OxTlorder(c, ext), 3, "line order");
        emon.Testport.AssertEq(Ocr.OxDeskew(c, ext), -85, "deskew in centi-degrees");
        emon.Testport.AssertEq(Ocr.OxOsd(c, ext), 90, "OSD degrees");
        emon.Testport.AssertEq(Ocr.OxScript(c, ext), 1281455214, "script, packed");
        emon.Testport.AssertEq(Ocr.OxSconf(c, ext), 17, "script confidence");
        emon.Testport.AssertEq(Ocr.OxOconf(c, ext), 187, "orientation confidence");
        emon.Testport.AssertEq(Ocr.OxNlines(c, ext), 1, "one line");
        int l = Ocr.OxLineAt(c, ext, 0);
        emon.Testport.AssertEq(l, ext + Ocr.OxHeader(), "the line list follows the header");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, l + 6), 80, "baseline end x");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, l + 10), 1, "block type");
        emon.Testport.AssertEq(Ocr.OxFirstWord(c, ext), l + Ocr.OxLineStride(), "the word list follows the lines");
        int wx0 = Ocr.OxFirstWord(c, ext);
        emon.Testport.AssertEq(Ocr.OxWflags(c, wx0), 65, "bold and mono");
        emon.Testport.AssertEq(Ocr.OxWlang(c, wx0), 1701734144, "eng");
        emon.Testport.AssertEq(Ocr.OxNsym(c, wx0), 2, "two symbols");
        int sy0 = Ocr.OxFirstSym(c, wx0);
        emon.Testport.AssertEq(emon.Port.CellsAt(c, sy0 + 4), 950, "symbol confidence");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, sy0 + 5), 1, "one code point");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, sy0 + 6), 2, "two alternatives");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, sy0 + 7), 72, "H");
        int al0 = Ocr.OxSymAlts(c, sy0);
        int al1 = Ocr.OxAltNext(c, al0);
        emon.Testport.AssertEq(emon.Port.CellsAt(c, al0), 1, "the first alternative has one code point");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, al0 + 1), 120, "its confidence");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, al0 + 2), 75, "K");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, al1), 2, "the second has two");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, al1 + 3), 77, "its second code point");
        emon.Testport.AssertEq(Ocr.OxAltNext(c, al1), Ocr.OxSymNext(c, sy0), "the next symbol follows the alternatives");
        int wx1 = Ocr.OxWordNext(c, wx0);
        emon.Testport.AssertEq(Ocr.OxNsym(c, wx1), 1, "the second word has one symbol");
        int s = Ocr.OxFirstSym(c, wx1);
        emon.Testport.AssertEq(emon.Port.CellsAt(c, s + 7), 33, "!");
        emon.Testport.AssertEq(Ocr.OxWordNext(c, wx1), emon.Port.CellsLen(c), "and is the last thing in the answer");
    }
